headings.text:
Can I attach a ref to the top-level HTMLDivElement? Although there is no prop exposed to do this directly, you can use a callback ref for this. const [ref] = useResizeObserver<HTMLDivElement>();

const listRef = useCallback(
 (api: ListImperativeAPI) => {
 const element = api?.element ?? null;

 switch (typeof ref) {
 case "function": {
 ref(element);
 break;
 }
 case "object": {
 if (ref !== null) {
 ref.current = element;
 }
 break;
 }
 }
 },
 [ref]
);

<List listRef={listRef} {...rest} />;

